:root {
  color-scheme: light;
  --paper: #f3f0e8;
  --ink: #20251f;
  --muted: #73786f;
  --line: #d7d6cd;
  --lime: #d8ff63;
  --forest: #263b2d;
  --white: #fffef9;
  --orange: #e7773d;
}

* { box-sizing: border-box; }

html, body { min-height: 100%; }

body {
  margin: 0;
  background: #dad8d0;
  color: var(--ink);
  font-family: Pretendard, "Noto Sans KR", "Apple SD Gothic Neo", system-ui, sans-serif;
  -webkit-font-smoothing: antialiased;
}

button, a { font: inherit; }
button { color: inherit; }
svg { fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }

.page-shell {
  min-height: 100vh;
  display: grid;
  grid-template-columns: minmax(390px, 480px) 360px;
  justify-content: center;
  align-items: center;
  gap: 96px;
  padding: 48px;
}

.phone {
  position: relative;
  width: 100%;
  min-height: 844px;
  overflow: hidden;
  background: var(--paper);
  border-radius: 32px;
  box-shadow: 0 24px 72px rgba(39, 44, 36, .18);
  padding: 22px 24px 130px;
}

.topbar { height: 52px; display: flex; align-items: center; justify-content: space-between; }
.brand { color: var(--ink); font-size: 24px; font-weight: 850; letter-spacing: -.08em; text-decoration: none; }
.brand-dot { color: var(--orange); }
.icon-button { width: 44px; height: 44px; border: 0; border-radius: 50%; background: transparent; display: grid; place-items: center; cursor: pointer; }
.icon-button:hover { background: rgba(32, 37, 31, .06); }
.icon-button:focus-visible, .primary-button:focus-visible, .reset-button:focus-visible { outline: 3px solid var(--orange); outline-offset: 3px; }
.icon-button svg { width: 21px; height: 21px; }

.context-line { display: flex; justify-content: space-between; align-items: center; margin-top: 4px; color: var(--muted); font-size: 12px; font-weight: 650; }
.location { display: flex; align-items: center; gap: 4px; }
.location svg { width: 15px; height: 15px; }

.hero { padding-top: 30px; }
.eyebrow { margin: 0 0 4px; color: var(--muted); font-size: 13px; font-weight: 700; }
.time-lockup { display: flex; align-items: baseline; gap: 6px; }
.time-lockup strong { font-family: Georgia, "Times New Roman", serif; font-size: clamp(82px, 24vw, 108px); font-weight: 400; line-height: .9; letter-spacing: -.07em; }
.time-lockup span { font-size: 21px; font-weight: 800; }
.hero h1 { margin: 18px 0 9px; font-size: 26px; line-height: 1.24; letter-spacing: -.045em; }
.next-class { margin: 0; color: var(--muted); font-size: 12px; }

.gap-map { margin-top: 31px; }
.gap-labels { display: flex; justify-content: space-between; margin-bottom: 7px; color: var(--muted); font-size: 10px; font-weight: 700; }
.timeline { display: flex; width: 100%; height: 46px; overflow: hidden; border: 1px solid rgba(32, 37, 31, .22); border-radius: 11px; background: rgba(255,255,255,.45); }
.segment { flex: var(--grow); min-width: 0; display: grid; place-items: center; border-right: 1px solid rgba(32, 37, 31, .16); font-size: 10px; font-weight: 800; transition: flex-grow .65s cubic-bezier(.2,.75,.2,1), background .45s ease, color .45s ease, transform .45s ease; }
.segment:last-child { border-right: 0; }
.segment-gap { background: repeating-linear-gradient(135deg, rgba(38,59,45,.08) 0 5px, transparent 5px 10px); color: var(--forest); }
.segment-move { background: #e4e2d9; color: #5f625c; }
.segment-focus { background: var(--lime); color: #223223; }
.segment-buffer { background: #ffd7bd; color: #723c22; }
.result-legend { display: none; justify-content: space-between; gap: 8px; margin-top: 9px; color: var(--muted); font-size: 9px; font-weight: 700; }
.result-legend.visible { display: flex; animation: fade-up .4s ease both; }
.result-legend span { display: flex; align-items: center; gap: 4px; white-space: nowrap; }
.dot { width: 6px; height: 6px; border-radius: 50%; }
.dot-move { background: #a4a69f; }.dot-focus { background: #92ba16; }.dot-buffer { background: #e99158; }

.constraints { margin-top: 28px; }
.section-heading { display: flex; justify-content: space-between; align-items: baseline; }
.section-heading h2 { margin: 0; font-size: 16px; letter-spacing: -.03em; }
.section-heading span { color: var(--muted); font-size: 10px; }
.chips { display: flex; gap: 6px; margin-top: 12px; overflow: hidden; }
.chip { min-height: 35px; padding: 0 10px; border: 1px solid var(--line); border-radius: 18px; background: rgba(255,255,255,.44); display: inline-flex; align-items: center; gap: 5px; white-space: nowrap; font-size: 10px; font-weight: 750; }
.chip svg { width: 14px; height: 14px; }

.mission { display: none; margin-top: 22px; padding-top: 20px; border-top: 1px solid var(--line); }
.mission.visible { display: block; animation: reveal .65s cubic-bezier(.2,.75,.2,1) both; }
.mission-kicker { display: flex; justify-content: space-between; align-items: center; color: var(--forest); font-size: 10px; font-weight: 850; text-transform: uppercase; letter-spacing: .04em; }
.fit { padding: 5px 8px; border-radius: 12px; background: rgba(216,255,99,.7); letter-spacing: 0; }
.mission h2 { margin: 11px 0 8px; font-size: 23px; line-height: 1.22; letter-spacing: -.04em; }
.mission p { margin: 0; color: var(--muted); font-size: 12px; line-height: 1.55; }
.mission-meta { display: flex; flex-wrap: wrap; gap: 7px 13px; margin-top: 13px; font-size: 10px; font-weight: 750; }
.mission-meta span::before { content: "·"; margin-right: 4px; color: var(--orange); }

.action-dock { position: absolute; z-index: 4; left: 0; right: 0; bottom: 0; padding: 12px 24px 20px; background: linear-gradient(180deg, rgba(243,240,232,0), var(--paper) 18%, var(--paper) 100%); }
.decision-note { margin: 0 0 9px; color: var(--muted); text-align: center; font-size: 10px; }
.primary-button { width: 100%; min-height: 58px; padding: 0 18px 0 22px; border: 0; border-radius: 14px; background: var(--forest); color: white; display: flex; align-items: center; justify-content: space-between; font-size: 15px; font-weight: 800; cursor: pointer; box-shadow: 0 8px 24px rgba(38,59,45,.16); transition: transform .16s ease, background .2s ease; }
.primary-button:hover { background: #1b3023; }
.primary-button:active { transform: translateY(1px) scale(.995); }
.primary-button svg { width: 22px; height: 22px; }
.primary-button.loading { cursor: wait; }
.primary-button.loading svg { animation: nudge .65s ease-in-out infinite alternate; }
.reset-button { display: block; width: 100%; min-height: 44px; margin-top: 4px; border: 0; background: transparent; color: var(--muted); font-size: 11px; font-weight: 700; cursor: pointer; }
.reset-button[hidden] { display: none; }

.desktop-note { display: block; max-width: 350px; }
.desktop-eyebrow { margin: 0 0 20px; color: var(--orange); font-size: 11px; font-weight: 850; letter-spacing: .18em; }
.desktop-note h2 { margin: 0; font-family: Georgia, "Times New Roman", serif; font-size: 50px; font-weight: 400; line-height: 1.05; letter-spacing: -.045em; }
.desktop-note > p:not(.desktop-eyebrow):not(.desktop-foot) { margin: 24px 0 0; color: #555b52; font-size: 15px; line-height: 1.75; }
.desktop-rule { width: 48px; height: 2px; margin: 32px 0 22px; background: var(--orange); }
.desktop-foot { color: #777b74; font-size: 11px; line-height: 1.7; }

@keyframes reveal { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: translateY(0); } }
@keyframes fade-up { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: translateY(0); } }
@keyframes nudge { to { transform: translateX(4px); } }

@media (max-width: 760px) {
  body { background: var(--paper); }
  .page-shell { min-height: 100vh; display: block; padding: 0; }
  .phone { width: 100%; min-height: 100vh; border-radius: 0; box-shadow: none; padding-top: max(22px, env(safe-area-inset-top)); padding-bottom: 126px; }
  .desktop-note { display: none; }
}

@media (max-height: 760px) and (max-width: 760px) {
  .hero { padding-top: 18px; }
  .time-lockup strong { font-size: 78px; }
  .hero h1 { margin-top: 12px; font-size: 23px; }
  .gap-map { margin-top: 20px; }
  .constraints { margin-top: 20px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
}

(() => {
  'use strict';

  const button = document.querySelector('#primaryButton');
  const resetButton = document.querySelector('#resetButton');
  const timeline = document.querySelector('#timeline');
  const mission = document.querySelector('#mission');
  const legend = document.querySelector('#resultLegend');
  const decisionNote = document.querySelector('#decisionNote');
  const label = button.querySelector('.button-label');

  const initialTimeline = '<div class="segment segment-gap" style="--grow:42"><span>빈 시간 42분</span></div>';
  const plannedTimeline = [
    '<div class="segment segment-move" style="--grow:6"><span>6</span></div>',
    '<div class="segment segment-focus" style="--grow:20"><span>과제 20</span></div>',
    '<div class="segment segment-buffer" style="--grow:8"><span>8</span></div>',
    '<div class="segment segment-move" style="--grow:8"><span>8</span></div>'
  ].join('');

  let timer;

  function buildPlan() {
    if (button.disabled) return;
    button.disabled = true;
    button.classList.add('loading');
    label.textContent = '조건을 맞추는 중…';
    decisionNote.textContent = '시간표 · 위치 · 준비물 · 집중도를 함께 보고 있어요.';

    timer = window.setTimeout(() => {
      timeline.innerHTML = plannedTimeline;
      mission.classList.add('visible');
      mission.setAttribute('aria-hidden', 'false');
      legend.classList.add('visible');
      label.textContent = '20분 미션 시작하기';
      button.classList.remove('loading');
      button.disabled = false;
      resetButton.hidden = false;
      decisionNote.textContent = '42분 안에 끝나도록 이동과 완충 시간까지 남겼어요.';
      document.body.dataset.state = 'planned';
    }, 850);
  }

  function resetPlan() {
    window.clearTimeout(timer);
    timeline.innerHTML = initialTimeline;
    mission.classList.remove('visible');
    mission.setAttribute('aria-hidden', 'true');
    legend.classList.remove('visible');
    label.textContent = '내 공강으로 만들기';
    button.classList.remove('loading');
    button.disabled = false;
    resetButton.hidden = true;
    decisionNote.textContent = '이동 시간과 다음 수업 준비까지 계산했어요.';
    delete document.body.dataset.state;
    button.focus({ preventScroll: true });
  }

  button.addEventListener('click', buildPlan);
  resetButton.addEventListener('click', resetPlan);
})();

